          "\u09A8\u09CB\u09A8\u09BE \u09AA\u09BE\u09A8\u09BF \u09AA\u09CD\u09B0\u09AC\u09C7\u09B6\u09C7\u09B0 \u099D\u09C1\u0981\u0995\u09BF \u09A5\u09BE\u0995\u09BE \u09B8\u09A4\u09CD\u09A4\u09CD\u09AC\u09C7\u0993 \u09AC\u09CB\u09B0\u09CB \u099A\u09BE\u09B7\u09C7 \u0986\u0997\u09CD\u09B0\u09B9\u09C0 \u0995\u09C3\u09B7\u0995"
